import{_ as a,o as e,c as s,ae as t}from"./chunks/framework.BmsPYn1i.js";const k=JSON.parse('{"title":"TPSのサンプルプログラム","description":"","frontmatter":{},"headers":[],"relativePath":"SamplePrograms/TPS.md","filePath":"SamplePrograms/TPS.md"}'),l={name:"SamplePrograms/TPS.md"};function n(o,i,h,r,d,c){return e(),s("div",null,[...i[0]||(i[0]=[t(`<h1 id="tpsのサンプルプログラム" tabindex="-1">TPSのサンプルプログラム <a class="header-anchor" href="#tpsのサンプルプログラム" aria-label="Permalink to &quot;TPSのサンプルプログラム&quot;">​</a></h1><p>キャラクターを三人称視点（TPS: Third Person Shooter）で操作して、 歩き回るロボットの敵を弾丸で倒すゲームです。敵を全部（10体）倒すと クリア、敵にぶつかられてLIFEが0になるか、フィールドから落ちると ゲームオーバーです。ときどき出現するアヒルの回復アイテムを取ると LIFEが回復します。</p><p><strong><a href="../samples/TPS.html" target="_blank">▶ TPSを実行する</a></strong> （ソースを見るにはページを開いてブラウザの「ページのソースを表示」を 使うか、リンク先を保存してください）</p><h2 id="操作方法" tabindex="-1">操作方法 <a class="header-anchor" href="#操作方法" aria-label="Permalink to &quot;操作方法&quot;">​</a></h2><ul><li>PC — W/A/S/Dキーで移動、矢印キーで方向転換、Spaceキーでジャンプ、 Enterキーで弾丸発射。マウスでも方向転換（PointerLock中）と クリックで発射ができます。</li><li>スマホ — 左ジョイスティックで移動、右ジョイスティックで方向転換、 「L」ボタンでジャンプ、「R」ボタンで弾丸発射。</li></ul><h2 id="このプログラムの特徴" tabindex="-1">このプログラムの特徴 <a class="header-anchor" href="#このプログラムの特徴" aria-label="Permalink to &quot;このプログラムの特徴&quot;">​</a></h2><h3 id="dynamiccharacterモードのプレイヤー" tabindex="-1">DynamicCharacterモードのプレイヤー <a class="header-anchor" href="#dynamiccharacterモードのプレイヤー" aria-label="Permalink to &quot;DynamicCharacterモードのプレイヤー&quot;">​</a></h3><p>プレイヤー（<code>vesma9.a3</code>）は<code>DynamicCharacter</code>モードで動かして います。毎フレームの<code>update(dt)</code>で、ジョイスティックの入力から 速度ベクトルを組み立てて<code>setLinearVelocity()</code>で移動、 <code>setAngularVelocity()</code>で方向転換しています。 <code>getUnitVecX()</code>/<code>getUnitVecZ()</code>で「自分の向きから見た前後左右」の ベクトルが取れるので、キャラクターの向き基準の移動が簡単に書けます。</p><p>ジャンプは<code>isGrounded()</code>（接地判定）と自前の上方向速度の組み合わせで 実現しています。</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.upSpeed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">9.8</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dt);       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 重力</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">isGrounded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()) {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.upSpeed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;              </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 着地したらリセット</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (view.leftButton) </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">this</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.upSpeed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ジャンプ</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>また<code>setAutoAction(true)</code>により、移動速度に応じて止まる・歩く・ 走るのアニメーションが自動で切り替わります（詳しくは <a href="./../FeaturesIntroduction/AutoDirectionAndAction/">向きとアクションの自動制御</a>）。</p><h3 id="クラスごとに役割を持たせた敵・弾丸・アイテム" tabindex="-1">クラスごとに役割を持たせた敵・弾丸・アイテム <a class="header-anchor" href="#クラスごとに役割を持たせた敵・弾丸・アイテム" aria-label="Permalink to &quot;クラスごとに役割を持たせた敵・弾丸・アイテム&quot;">​</a></h3><ul><li>敵（<code>RobotExpressive.glb</code>、<code>DynamicCharacter</code>モード）は、 フィールドの境界で跳ね返りながら歩き回ります。 <code>setAutoDirection(true)</code>で進行方向を自動で向きます。 弾丸が当たると消えてスコアが100点入ります。</li><li>弾丸（<code>bullet.a3</code>、<code>SimplePhysics</code>モード）は発射時に <code>setLinearVelocity()</code>で前方斜め上に打ち出され、あとは物理演算で 放物線を描いて飛びます。何かに当たるか地面より下に落ちると 消えます。</li><li>回復アイテムのアヒル（<code>Duck.glb</code>）はメインループの中で毎フレーム 1000分の2の確率で出現し、一定時間で消えます。プレイヤーが 触れるとLIFEが100回復します。</li></ul><p>いずれも衝突時の処理は各クラスの<code>handleCollision()</code>に書かれて います。<code>obj instanceof Bullet</code>のように相手のクラスで処理を 分けるのがポイントです（詳しくは <a href="./../FeaturesIntroduction/CollisionDetection/">当たり判定</a>）。</p><h3 id="マウスによる視点操作-pointerlock" tabindex="-1">マウスによる視点操作（PointerLock） <a class="header-anchor" href="#マウスによる視点操作-pointerlock" aria-label="Permalink to &quot;マウスによる視点操作（PointerLock）&quot;">​</a></h3><p>ゲーム開始時に<code>requestPointerLock()</code>でマウスカーソルを画面に 固定し、マウスの移動量（<code>e.movementX</code>/<code>movementY</code>）から プレイヤーの向きとカメラの高さを変えています。FPS/TPSでよく使われる 操作方法です。</p><h3 id="そのほか" tabindex="-1">そのほか <a class="header-anchor" href="#そのほか" aria-label="Permalink to &quot;そのほか&quot;">​</a></h3><ul><li>フィールドは<code>grass-ground2.glb</code>を<code>meshCollider: &#39;tri_mesh&#39;</code>・ <code>rigidBody: &#39;fixed&#39;</code>の固定地形にしています。</li><li>カメラは<code>Follow</code>モードでプレイヤーを追いかけます。</li><li>LIFEとSCOREの表示はHTMLの要素に毎フレーム書き込んでいます。</li><li>BGM・効果音: <a href="https://maou.audio" target="_blank" rel="noreferrer">魔王魂</a></li></ul>`,18)])])}const E=a(l,[["render",n]]);export{k as __pageData,E as default};
